functions.showToolAuthorStudio:
function showToolAuthorStudio() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  if (typeof createConfigHeader === "function") {
    var header = createConfigHeader("ADMIN", "🔧", "Tool Author Studio", { marginBottom: "10px" });
    out.appendChild(header);
  }
  var tabBar = document.createElement("div");
  tabBar.style.cssText = "display:flex; gap:0; margin:0 12px 10px 12px; border-bottom:2px solid #e2e8f0;";
  var content = document.createElement("div");
  content.style.cssText = "padding:0 12px 12px 12px;";
  out.appendChild(tabBar);
  out.appendChild(content);
  var tabs = [
    { id: "catalog", label: "🎨 Tile",        render: _tasCatalogEditorTab },
    { id: "tool",    label: "🧩 Source",      render: _tasToolEditorTab },
    { id: "create",  label: "✨ AI Create",   render: _tasAiCreateTab },
    { id: "fix",     label: "🔧 AI Fix",      render: _tasAiFixTab },
    { id: "io",      label: "📦 Import/Export", render: _tasImportExportTab },
    { id: "history", label: "🕒 History",     render: _tasHistoryTab },
  ];
  var activeTab = "catalog";
  function paintTabs() {
    tabBar.innerHTML = "";
    tabs.forEach(function (t) {
      var btn = document.createElement("div");
      var on = activeTab === t.id;
      btn.style.cssText = "flex:1; text-align:center; padding:8px 4px; font-size:10px; font-weight:700; cursor:pointer; transition:all 0.2s; white-space:nowrap; " +
        (on ? "background:#fff; color:#1565c0; border-bottom:3px solid #1565c0; margin-bottom:-2px;" : "background:#f8fafc; color:#64748b; border-bottom:3px solid transparent;");
      btn.textContent = t.label;
      btn.onclick = function () {
        activeTab = t.id;
        paintTabs();
        content.innerHTML = "";
        t.render(content);
      };
      tabBar.appendChild(btn);
    });
  }
  paintTabs();
  // Initial render
  tabs.find(function (t) { return t.id === activeTab; }).render(content);
  if (typeof window.createPlatinumHomeBtn === "function") out.appendChild(window.createPlatinumHomeBtn());
}

functions._tasCatalogEditorTab:
function _tasCatalogEditorTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading catalog…</div>';
  loadFeatureData(STORE_CATALOG).then(function (rows) {
    var tiles = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (tiles.length === 0) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No catalog tiles yet. Import catalog.json or install tools to populate.</div>';
      return;
    }
    // Sort by category then order
    tiles.sort(function (a, b) {
      var ca = (a.category || "").toLowerCase(), cb = (b.category || "").toLowerCase();
      if (ca !== cb) return ca < cb ? -1 : 1;
      return (a.order || 999) - (b.order || 999);
    });
    var listHtml = '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">' + tiles.length + ' tile(s). Click a row to edit metadata. Edits set <code>userOverride:true</code> so re-imports won’t clobber.</div>';
    listHtml += tiles.map(function (t, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = t.icon || "🧩";
      var src = t.source ? '<span style="font-size:9px; color:#0d9488;">[' + _ebEsc(t.source) + ']</span>' : '<span style="font-size:9px; color:#94a3b8;">[built-in]</span>';
      var ovr = t.userOverride ? ' <span style="font-size:9px; background:#fef3c7; color:#92400e; padding:1px 5px; border-radius:0;">EDITED</span>' : '';
      return (
        '<div data-tas-tile="' + _ebEsc(t.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:8px 10px; margin-bottom:4px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
        '<div style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(t.title || t.id) + ovr + '</div>' +
        '<div style="font-size:9px; color:#64748b; margin-top:2px;">' + _ebEsc(t.category || "(no category)") + ' · ' + src + '</div>' +
        '</div>' +
        '<button class="tas-edit-btn" style="padding:3px 8px; font-size:10px; cursor:pointer; background:#1565c0; color:#fff; border:none;">Edit</button>' +
        '</div>'
      );
    }).join("");
    content.innerHTML = listHtml;
    content.querySelectorAll("[data-tas-tile]").forEach(function (row) {
      row.onclick = function () {
        var id = row.getAttribute("data-tas-tile");
        var tile = tiles.filter(function (t) { return t.id === id; })[0];
        if (tile) _tasOpenCatalogForm(tile, content);
      };
    });
  });
}

functions._tasOpenCatalogForm:
function _tasOpenCatalogForm(tile, content) {
  var formHtml =
    '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
    '<div style="background:#fff; border:1px solid #e2e8f0; padding:14px;">' +
    '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:10px;">Edit tile: ' + _ebEsc(tile.id) + '</div>' +
    _tasField("tasIcon", "Icon (emoji)", tile.icon || "", "text") +
    _tasField("tasTitle", "Title", tile.title || "", "text") +
    _tasField("tasDesc", "Description", tile.desc || "", "text") +
    _tasField("tasHover", "Hover tip", tile.hoverTip || "", "text") +
    _tasField("tasCat", "Category", tile.category || "", "text") +
    _tasField("tasOrder", "Order (number)", String(tile.order != null ? tile.order : ""), "number") +
    _tasField("tasTags", "Tags (comma-separated)", (tile.tags || []).join(", "), "text") +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasReqApi"' + (tile.requiresApiKey ? " checked" : "") + '> Requires API key</label>' +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasCore"' + (tile.core ? " checked" : "") + '> Core (always pinned)</label>' +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:6px 0;"><input type="checkbox" id="tasDefault"' + (tile.default ? " checked" : "") + '> Default (auto-pin on first load)</label>' +
    _tasField("tasAction", "Action (JS string, runs on click)", tile.action || "", "text") +
    '<div style="display:flex; gap:6px; margin-top:12px;">' +
    '<button id="tasSave" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">💾 Save</button>' +
    '<button id="tasCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
    '</div>' +
    '</div>';
  content.innerHTML = formHtml;
  document.getElementById("tasBack").onclick = function () { _tasCatalogEditorTab(content); };
  document.getElementById("tasCancel").onclick = function () { _tasCatalogEditorTab(content); };
  document.getElementById("tasSave").onclick = function () {
    var updated = Object.assign({}, tile, {
      icon: document.getElementById("tasIcon").value.trim(),
      title: document.getElementById("tasTitle").value.trim(),
      desc: document.getElementById("tasDesc").value.trim(),
      hoverTip: document.getElementById("tasHover").value.trim(),
      category: document.getElementById("tasCat").value.trim(),
      order: parseInt(document.getElementById("tasOrder").value, 10) || 0,
      tags: document.getElementById("tasTags").value.split(",").map(function (s) { return s.trim(); }).filter(Boolean),
      requiresApiKey: document.getElementById("tasReqApi").checked,
      core: document.getElementById("tasCore").checked,
      default: document.getElementById("tasDefault").checked,
      action: document.getElementById("tasAction").value,
      userOverride: true,
    });
    _tasSaveCatalogRow(updated).then(function () {
      showToast("✓ Tile saved.", "success");
      _tasCatalogEditorTab(content);
    });
  };
}

functions._tasField:
function _tasField(id, label, value, type) {
  return '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">' + _ebEsc(label) + '</label>' +
    '<input id="' + id + '" type="' + (type || "text") + '" value="' + _ebEsc(String(value)) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">';
}

functions._tasToolEditorTab:
function _tasToolEditorTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading tools…</div>';
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (tools.length === 0) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No tools installed. Install from Settings → Tool Manager.</div>';
      return;
    }
    var html = '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">' + tools.length + ' tool(s). Source = function code · Settings = tool-level metadata · Push = upload to CDN.</div>';
    html += tools.map(function (t, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = (t.catalog && t.catalog.icon) || "🧩";
      var lab = (t.catalog && t.catalog.title) || t.label || t.id;
      var ver = Number(t.__version) || 0;
      var fnCount = t.functions ? Object.keys(t.functions).length : 0;
      return (
        '<div data-tas-tool-row="' + _ebEsc(t.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:8px 10px; margin-bottom:4px; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
        '<div style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(lab) + (ver > 0 ? ' <span style="font-size:9px; color:#1565c0;">v' + ver + '</span>' : '') + '</div>' +
        '<div style="font-size:9px; color:#64748b; margin-top:2px;">id: ' + _ebEsc(t.id) + ' · ' + fnCount + ' function(s)</div>' +
        '</div>' +
        '<div style="display:flex; gap:4px; flex-shrink:0;">' +
        '<button data-tas-source="' + _ebEsc(t.id) + '" title="Edit function source" style="padding:3px 8px; font-size:10px; cursor:pointer; background:#0d9488; color:#fff; border:none;">📝 Source</button>' +
        '<button data-tas-settings="' + _ebEsc(t.id) + '" title="Edit tool-level settings (defaultEnabled, audience, label, version)" style="padding:3px 8px; font-size:10px; cursor:pointer; background:#fff; color:#0d9488; border:1px solid #0d9488;">⚙️ Settings</button>' +
        '<button data-tas-push="' + _ebEsc(t.id) + '" title="Push current tool JSON to CDN (eli-data)" style="padding:3px 8px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:700;">🚀 Push</button>' +
        '</div>' +
        '</div>'
      );
    }).join("");
    content.innerHTML = html;
    function findTool(id) { return tools.filter(function (t) { return t.id === id; })[0]; }
    content.querySelectorAll("[data-tas-source]").forEach(function (b) {
      b.onclick = function () { var t = findTool(b.getAttribute("data-tas-source")); if (t) _tasOpenToolForm(t, content); };
    });
    content.querySelectorAll("[data-tas-settings]").forEach(function (b) {
      b.onclick = function () { var t = findTool(b.getAttribute("data-tas-settings")); if (t) _tasOpenToolSettingsForm(t, content); };
    });
    content.querySelectorAll("[data-tas-push]").forEach(function (b) {
      b.onclick = function () { _tasPushToolToCdn(b.getAttribute("data-tas-push"), content); };
    });
  });
}

functions._tasOpenToolForm:
function _tasOpenToolForm(tool, content) {
  var fnNames = tool.functions ? Object.keys(tool.functions) : [];
  var initialFn = fnNames[0] || "";
  function paint(currentFnName) {
    var src = (tool.functions && tool.functions[currentFnName]) || "";
    var html =
      '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
      '<div style="background:#fff; border:1px solid #e2e8f0; padding:14px;">' +
      '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:8px;">' + _ebEsc(tool.id) + ' (v' + (Number(tool.__version) || 0) + ')</div>' +
      '<div style="display:flex; gap:8px; align-items:center; margin-bottom:6px;">' +
      '<label style="font-size:10px; font-weight:700; color:#64748b; text-transform:uppercase;">Function:</label>' +
      '<select id="tasFnSel" style="flex:1; padding:5px; font-size:11px; border:1px solid #cbd5e1;">' +
      fnNames.map(function (n) { return '<option value="' + _ebEsc(n) + '"' + (n === currentFnName ? " selected" : "") + '>' + _ebEsc(n) + '</option>'; }).join("") +
      '</select>' +
      '</div>' +
      '<textarea id="tasFnSrc" style="width:100%; min-height:280px; max-height:500px; padding:10px; font-family:ui-monospace,Consolas,monospace; font-size:11px; line-height:1.45; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box; white-space:pre; tab-size:2;">' + _ebEsc(src) + '</textarea>' +
      '<div id="tasValidateOut" style="font-size:10px; margin:6px 0; min-height:14px;"></div>' +
      '<div style="display:flex; gap:6px; margin-top:8px;">' +
      '<button id="tasValidate" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#0d9488; border:1px solid #0d9488; cursor:pointer;">🧪 Validate</button>' +
      '<button id="tasSaveFn" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">💾 Save & Re-eval</button>' +
      '<button id="tasCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
      '</div>' +
      '</div>';
    content.innerHTML = html;
    document.getElementById("tasBack").onclick = function () { _tasToolEditorTab(content); };
    document.getElementById("tasCancel").onclick = function () { _tasToolEditorTab(content); };
    document.getElementById("tasFnSel").onchange = function () { paint(this.value); };
    document.getElementById("tasValidate").onclick = function () {
      var out = document.getElementById("tasValidateOut");
      var src = document.getElementById("tasFnSrc").value;
      var err = _tasValidateSource(src);
      if (err) { out.innerHTML = '<span style="color:#dc2626;">❌ ' + _ebEsc(err) + '</span>'; }
      else { out.innerHTML = '<span style="color:#0d9488;">✓ Compiles cleanly.</span>'; }
    };
    document.getElementById("tasSaveFn").onclick = function () {
      var sel = document.getElementById("tasFnSel").value;
      var src = document.getElementById("tasFnSrc").value;
      var err = _tasValidateSource(src);
      if (err) { showToast("❌ Won't save — syntax error: " + err, "error"); return; }
      tool.functions[sel] = src;
      // Display version bumps automatically; timestamp drives actual update detection.
      tool.__version = (typeof window._eliBumpDisplayVersion === "function")
        ? window._eliBumpDisplayVersion(tool.__version)
        : ((Number(tool.__version) || 0) + 1);
      tool.releasedAt = new Date().toISOString();
      _tasSaveTool(tool).then(function () {
        showToast("✓ Saved " + sel + " (v" + tool.__version + ").", "success");
        _tasToolEditorTab(content);
      });
    };
  }
  paint(initialFn);
}
// Tool-level settings form. Edits the metadata fields that don't live in the
// catalog tile (which has its own form) and don't live in function source
// code (which has its own editor). These fields control runtime behavior:
//   - label             — top-level label (separate from catalog.title)
//   - __version         — manual version bump (Source-editor saves auto-bump
//                          this; this form lets you pin or jump it explicitly)
//   - defaultEnabled    — whether the tool's functions LOAD at boot for new
//                          users (orthogonal to catalog.default which auto-pins
//                          the tile on the dashboard)
//   - audience          — visibility tags array (e.g. ["all"] or [] for admin)
//   - audienceEmails    — explicit email allow-list (used when audience is [])

functions._tasOpenToolSettingsForm:
function _tasOpenToolSettingsForm(tool, content) {
  var html =
    '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
    '<div style="background:#fff; border:1px solid #e2e8f0; padding:14px;">' +
    '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:4px;">⚙️ Tool Settings: ' + _ebEsc(tool.id) + '</div>' +
    '<div style="font-size:10px; color:#64748b; margin-bottom:12px;">Tool-level metadata. For catalog tile (icon/title/desc) use the Catalog Editor tab. For function code use 📝 Source.</div>' +
    _tasField("tasSetLabel", "Label (top-level, distinct from catalog.title)", tool.label || "", "text") +
    _tasField("tasSetVersion", "Version (display label only — auto-bumps on push, e.g. \"1.2\")", String(tool.__version == null ? "1.0" : tool.__version), "text") +
    '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Category (Tool Manager grouping; same value as catalog.category)</label>' +
    '<input id="tasSetCategory" type="text" list="tasCategoryOptions" value="' + _ebEsc(String((tool.catalog && tool.catalog.category) || "")) + '" placeholder="Tools - ELI Core" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' +
    '<datalist id="tasCategoryOptions">' +
      '<option value="Tools - ELI Core">' +
      '<option value="Admin">' +
      '<option value="Engagement">' +
      '<option value="Accessibility">' +
      '<option value="Patents">' +
      '<option value="Data">' +
    '</datalist>' +
    '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; margin:8px 0;"><input type="checkbox" id="tasSetDefaultEnabled"' + (tool.defaultEnabled ? " checked" : "") + '> <strong>defaultEnabled</strong> — load the tool\'s functions at boot for new users</label>' +
    '<div style="margin-top:14px; padding:8px 10px; background:#fffbeb; border:1px solid #fde68a; border-left:3px solid #f59e0b; font-size:10.5px; color:#78350f; line-height:1.5;">' +
      '<strong>Visibility — three independent mechanisms.</strong> A user sees the tool if ANY of these match. Leave them all empty to make the tool admin-only (no one sees it).' +
      '<ul style="margin:6px 0 0 16px; padding:0;">' +
        '<li><strong>Audience tags</strong> — use <code>all</code> for everyone, or custom tags that match user-side <code>audienceTags</code>.</li>' +
        '<li><strong>Audience emails</strong> — specific email addresses (e.g. one teammate). Exact match, case-insensitive.</li>' +
        '<li><strong>Audience email domains</strong> — whole companies (e.g. <code>@colpal.com</code>). Anyone with an email at that domain sees the tool.</li>' +
      '</ul>' +
    '</div>' +
    _tasField("tasSetAudience", "Audience tags (comma-separated — use \"all\" for everyone, or leave empty to restrict via the email/domain fields below)", (Array.isArray(tool.audience) ? tool.audience.join(", ") : ""), "text") +
    '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience emails (one per line — grant access to specific people by their email address)</label>' +
    '<textarea id="tasSetAudienceEmails" placeholder="someone@colpal.com&#10;another.person@colpal.com" style="width:100%; min-height:60px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(tool.audienceEmails) ? tool.audienceEmails.join("\n") : "")) + '</textarea>' +
    '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience email domains (one per line — grant access to anyone at a domain, e.g. @colpal.com)</label>' +
    '<textarea id="tasSetAudienceEmailDomains" placeholder="@colpal.com&#10;@example.com" style="width:100%; min-height:60px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(tool.audienceEmailDomains) ? tool.audienceEmailDomains.join("\n") : "")) + '</textarea>' +
    '<div style="display:flex; gap:6px; margin-top:12px;">' +
    '<button id="tasSetSave" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">💾 Save (local)</button>' +
    '<button id="tasSetCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
    '</div>' +
    '<div style="margin-top:8px; font-size:10px; color:#64748b; line-height:1.4;">Saves to local IDB only. To publish, click <strong>🚀 Push</strong> on the tool list once your edits (here + Source + Catalog) are complete.</div>' +
    '</div>';
  content.innerHTML = html;
  document.getElementById("tasBack").onclick = function () { _tasToolEditorTab(content); };
  document.getElementById("tasSetCancel").onclick = function () { _tasToolEditorTab(content); };
  document.getElementById("tasSetSave").onclick = function () {
    var label = document.getElementById("tasSetLabel").value.trim();
    var versionVal = document.getElementById("tasSetVersion").value.trim() || "1.0";
    var defEn = !!document.getElementById("tasSetDefaultEnabled").checked;
    var audRaw = document.getElementById("tasSetAudience").value;
    var audience = audRaw.split(",").map(function (s) { return s.trim(); }).filter(Boolean);
    var emailsRaw = document.getElementById("tasSetAudienceEmails").value;
    var audienceEmails = emailsRaw.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean);
    var domainsRaw = document.getElementById("tasSetAudienceEmailDomains").value;
    var audienceEmailDomains = domainsRaw.split(/\r?\n/).map(function (s) {
      var v = s.trim();
      // Normalize: ensure leading "@" so users can type "colpal.com" or "@colpal.com" interchangeably.
      if (v && v.charAt(0) !== "@") v = "@" + v;
      return v;
    }).filter(Boolean);
    var category = document.getElementById("tasSetCategory").value.trim();
    if (label) tool.label = label;
    tool.__version = versionVal;
    tool.defaultEnabled = defEn;
    // Category lives in the catalog tile (single source of truth in the tool
    // JSON). Push will mirror it to the manifest's top-level `category` so
    // Tool Manager's grouping stays consistent.
    if (!tool.catalog) tool.catalog = {};
    tool.catalog.category = category;
    if (audience.length) tool.audience = audience; else delete tool.audience;
    if (audienceEmails.length) tool.audienceEmails = audienceEmails; else delete tool.audienceEmails;
    if (audienceEmailDomains.length) tool.audienceEmailDomains = audienceEmailDomains; else delete tool.audienceEmailDomains;
    _tasSaveTool(tool).then(function () {
      showToast("✓ Settings saved (v" + tool.__version + ").", "success");
      _tasToolEditorTab(content);
    });
  };
}
// GitHub helpers — local copies of ALP's _alpGitHubGet / _alpGitHubPut so TAS
// can push without depending on ALP being installed. Same wire format. PAT/
// repo/branch are read from the same localStorage keys ALP uses, so a single
// admin login covers both tools.

functions._tasGhGet:
function _tasGhGet(pat, repo, branch, filePath) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
    "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
  return fetch(url, {
    cache: "no-store",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  }).then(function (r) {
    if (r.status === 404) return null;
    if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

functions._tasGhPut:
function _tasGhPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
  // UTF-8 → base64 (matches ALP's helper exactly, handles unicode correctly).
  var bytes = new TextEncoder().encode(contentStr);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  var body = { message: message, content: btoa(bin), branch: branch };
  if (existingSha) body.sha = existingSha;
  return fetch(url, {
    method: "PUT",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  }).then(function (r) {
    if (!r.ok) return r.text().then(function (t) { throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}
// Push a tool's current IDB state to the eli-data CDN. Two-step write:
//   1) PUT <id>.json with the tool payload (wrapped in the standard
//      sectionVersions/sections envelope the loader expects)
//   2) PATCH tools-manifest-v2.json — find the matching tools[] entry, bump
//      version + size + changelog + lastUpdated, PUT it back
// Bumps tool.__version automatically (matches Source-editor save behavior).
// Confirmation modal collects a changelog string before kicking off.

functions._tasPushToolToCdn:
function _tasPushToolToCdn(toolId, content) {
  // Reuse ALP's localStorage keys so admin only has to set credentials once.
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  if (!pat) {
    showToast("❌ No GitHub PAT set. Open Admin Library Publisher and configure your PAT first.", "error");
    return;
  }
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tool = (rows || []).filter(function (r) { return r && r.id === toolId; })[0];
    if (!tool) { showToast("❌ Tool not found in IDB.", "error"); return; }
    // Display version is a free-form label that auto-bumps on push (1.0→1.1→…→1.9→2.0).
    // Actual update detection uses the timestamps stamped below — this string
    // is purely for human-readable changelogs and "v1.2 → v1.3" toasts.
    var nextVer = (typeof window._eliBumpDisplayVersion === "function")
      ? window._eliBumpDisplayVersion(tool.__version)
      : ((Number(tool.__version) || 0) + 1);
    var defaultLog = "v" + nextVer + " · pushed via Tool Author Studio";
    // Confirmation overlay — small modal with a changelog input.
    var overlay = document.createElement("div");
    overlay.id = "tasPushOverlay";
    overlay.style.cssText = "position:fixed; inset:0; z-index:99999; background:rgba(15,23,42,0.55); display:flex; align-items:center; justify-content:center; padding:20px;";
    overlay.innerHTML =
      '<div style="background:#fff; width:min(520px,96vw); border:1px solid #cbd5e1; box-shadow:0 24px 60px rgba(15,23,42,0.45); padding:18px; font-family:Inter,system-ui,sans-serif;">' +
      '<div style="font-size:13px; font-weight:800; color:#0f172a; margin-bottom:8px;">🚀 Push ' + _ebEsc(toolId) + ' v' + nextVer + ' to CDN</div>' +
      '<div style="font-size:11px; color:#64748b; margin-bottom:12px;">Repo: <code>' + _ebEsc(repo) + '</code> · branch: <code>' + _ebEsc(branch) + '</code></div>' +
      '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin-bottom:4px; text-transform:uppercase;">Changelog</label>' +
      '<textarea id="tasPushLog" style="width:100%; min-height:60px; padding:8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' + _ebEsc(defaultLog) + '</textarea>' +
      '<div id="tasPushStatus" style="font-size:10px; color:#64748b; margin:8px 0; min-height:14px;"></div>' +
      '<div style="display:flex; gap:6px;">' +
      '<button id="tasPushGo" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; cursor:pointer;">🚀 Push</button>' +
      '<button id="tasPushCancel" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
      '</div>' +
      '</div>';
    document.body.appendChild(overlay);
    var goBtn = document.getElementById("tasPushGo");
    var cancelBtn = document.getElementById("tasPushCancel");
    var statusEl = document.getElementById("tasPushStatus");
    cancelBtn.onclick = function () { overlay.remove(); };
    overlay.onclick = function (e) { if (e.target === overlay) overlay.remove(); };
    goBtn.onclick = function () {
      var changelog = document.getElementById("tasPushLog").value.trim() || defaultLog;
      goBtn.disabled = true;
      cancelBtn.disabled = true;
      function setStatus(msg) { statusEl.textContent = msg; }
      // 1) Bump version + stamp releasedAt fresh, build the canonical envelope.
      tool.__version = nextVer;
      tool.releasedAt = new Date().toISOString();
      var payload = {
        schemaVersion: 1,
        exportedAt: new Date().toISOString(),
        sectionVersions: { jsonTools: 1 },
        sections: { jsonTools: [tool] },
      };
      var payloadStr = JSON.stringify(payload, null, 2);
      var fileName = toolId + ".json";
      setStatus("Fetching " + fileName + " current sha…");
      _tasGhGet(pat, repo, branch, fileName).then(function (existing) {
        var sha = existing && existing.sha ? existing.sha : undefined;
        setStatus("Uploading " + fileName + " (" + (payloadStr.length / 1024).toFixed(1) + " KB)…");
        return _tasGhPut(pat, repo, branch, fileName, payloadStr, "[TAS] " + toolId + " v" + nextVer + ": " + changelog.split(/\r?\n/)[0].slice(0, 80), sha);
      }).then(function () {
        setStatus("Updating tools-manifest-v2.json…");
        return _tasGhGet(pat, repo, branch, "tools-manifest-v2.json");
      }).then(function (mfFile) {
        if (!mfFile || !mfFile.content) throw new Error("Manifest not found in repo.");
        // GitHub returns base64-encoded content. Decode UTF-8-safely (atob
        // returns binary string; need TextDecoder to get actual UTF-8 text).
        var b64 = String(mfFile.content).replace(/\s/g, "");
        var binStr = atob(b64);
        var bytes = new Uint8Array(binStr.length);
        for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
        var manifestStr = new TextDecoder("utf-8").decode(bytes);
        var manifest;
        try { manifest = JSON.parse(manifestStr); } catch (e) { throw new Error("Manifest JSON parse failed: " + e.message); }
        if (!manifest || !Array.isArray(manifest.tools)) throw new Error("Manifest has no tools[] array.");
        var entry = manifest.tools.filter(function (e) { return e && e.id === toolId; })[0];
        if (!entry) {
          // First-time push of a tool that wasn't previously in the manifest.
          // Add a new entry with sensible defaults sourced from the tool itself.
          entry = {
            id: toolId,
            version: nextVer,
            lastUpdated: tool.releasedAt, // mirrors file's releasedAt — drives update detection
            filename: fileName,
            size: payloadStr.length,
            label: tool.label || (tool.catalog && tool.catalog.title) || toolId,
            kind: "tool",
            category: (tool.catalog && tool.catalog.category) || "Tools - ELI Core",
            audience: Array.isArray(tool.audience) ? tool.audience : (tool.defaultEnabled === false ? [] : ["all"]),
            changelog: changelog,
          };
          if (Array.isArray(tool.audienceEmails) && tool.audienceEmails.length) {
            entry.audienceEmails = tool.audienceEmails;
          }
          if (Array.isArray(tool.audienceEmailDomains) && tool.audienceEmailDomains.length) {
            entry.audienceEmailDomains = tool.audienceEmailDomains;
          }
          manifest.tools.push(entry);
        } else {
          entry.version = nextVer;
          entry.lastUpdated = tool.releasedAt; // refresh the per-tool timestamp
          entry.size = payloadStr.length;
          entry.changelog = changelog;
          if (tool.label) entry.label = tool.label;
          // Sync category from the catalog tile (single source of truth in the
          // tool JSON) to the manifest entry so Tool Manager's grouping/filter
          // sees the latest value.
          if (tool.catalog && tool.catalog.category) entry.category = tool.catalog.category;
          if (Array.isArray(tool.audience)) entry.audience = tool.audience;
          if (Array.isArray(tool.audienceEmails) && tool.audienceEmails.length) {
            entry.audienceEmails = tool.audienceEmails;
          } else if (entry.audienceEmails) {
            delete entry.audienceEmails;
          }
          if (Array.isArray(tool.audienceEmailDomains) && tool.audienceEmailDomains.length) {
            entry.audienceEmailDomains = tool.audienceEmailDomains;
          } else if (entry.audienceEmailDomains) {
            delete entry.audienceEmailDomains;
          }
        }
        manifest.lastUpdated = new Date().toISOString();
        var newManifestStr = JSON.stringify(manifest, null, 2);
        return _tasGhPut(pat, repo, branch, "tools-manifest-v2.json", newManifestStr, "[TAS] manifest: " + toolId + " v" + nextVer, mfFile.sha);
      }).then(function () {
        setStatus("✓ Pushed.");
        // Persist the bumped version to local IDB so the local copy stays in
        // sync with what's now on the CDN (otherwise next save would re-bump
        // from the pre-push number).
        return _tasSaveTool(tool);
      }).then(function () {
        showToast("✓ Pushed " + toolId + " v" + nextVer + " to CDN.", "success");
        overlay.remove();
        _tasToolEditorTab(content);
      }).catch(function (e) {
        setStatus("❌ " + (e && e.message ? e.message : String(e)));
        goBtn.disabled = false;
        cancelBtn.disabled = false;
      });
    };
  });
}

functions._tasValidateSource:
function _tasValidateSource(src) {
  if (!src || !src.trim()) return "Empty source";
  try { new Function("return (\n" + src + "\n);"); return null; }
  catch (e) { return e && e.message ? e.message : "Unknown syntax error"; }
}

functions._tasSaveCatalogRow:
function _tasSaveCatalogRow(row) {
  return loadFeatureData(STORE_CATALOG).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    byId[row.id] = row;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_CATALOG, newRows);
  }).then(function () {
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      return _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
  });
}

functions._tasSaveTool:
function _tasSaveTool(tool) {
  return loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    // Auto-snapshot the PREVIOUS state of this tool before overwriting (history
    // tab can roll back). No-op for brand-new tools.
    if (byId[tool.id] && typeof _tasSnapshotTool === "function") {
      _tasSnapshotTool(byId[tool.id]);
    }
    byId[tool.id] = tool;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_JSON_TOOLS, newRows);
  }).then(function () {
    // Re-eval the tool's functions immediately so changes take effect without reload.
    try {
      if (tool.functions && typeof tool.functions === "object") {
        Object.keys(tool.functions).forEach(function (fnName) {
          var src = tool.functions[fnName];
          if (typeof src === "string" && src.length) {
            window[fnName] = new Function("return (\n" + src + "\n);")();
          }
        });
      }
    } catch (e) { console.warn("[TAS] re-eval after save failed:", e); }
    // Sync catalog in case the tool's catalog block changed (it's the same row).
    if (typeof _dataHubSyncToolsToCatalog === "function") return _dataHubSyncToolsToCatalog();
  });
}

functions._tasNewChat:
function _tasNewChat() {
  return { messages: [] }; // { role: "user"|"assistant", content: string }
}

// Append a turn to a chat object (messages = system+user+assistant turns).

functions._tasChatAppend:
function _tasChatAppend(chat, role, content) {
  if (!chat || !chat.messages) return;
  chat.messages.push({ role: role, content: String(content || "") });
}

// Render the chat transcript into a host element (scrollable, auto-scroll).

functions._tasRenderChat:
function _tasRenderChat(chat, host) {
  if (!host) return;
  host.innerHTML = chat.messages.map(function (m) {
    var bg = m.role === "user" ? "#e0f2fe" : "#f1f5f9";
    var color = m.role === "user" ? "#0c4a6e" : "#334155";
    var lbl = m.role === "user" ? "YOU" : "AI";
    var lblColor = m.role === "user" ? "#0369a1" : "#64748b";
    return (
      '<div style="margin-bottom:8px;">' +
      '<div style="font-size:9px; font-weight:800; color:' + lblColor + '; letter-spacing:0.6px; margin-bottom:2px;">' + lbl + '</div>' +
      '<div style="background:' + bg + '; color:' + color + '; padding:8px 10px; font-size:11px; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; border-left:2px solid ' + lblColor + ';">' +
      _ebEsc(m.content) +
      '</div>' +
      '</div>'
    );
  }).join("");
  host.scrollTop = host.scrollHeight;
}

// Build a Gemini prompt that combines system instructions + chat transcript.

functions._tasBuildChatPrompt:
function _tasBuildChatPrompt(systemPrompt, chat) {
  var transcript = chat.messages.map(function (m) {
    return (m.role === "user" ? "USER: " : "ASSISTANT: ") + m.content;
  }).join("\n\n");
  return systemPrompt + "\n\n=== CONVERSATION SO FAR ===\n" + transcript + "\n\nASSISTANT:";
}

// Strip code fences and language hints from AI output.

functions._tasCleanCode:
function _tasCleanCode(s) {
  return String(s || "")
    .replace(/```(?:javascript|js|json)?\s*/gi, "")
    .replace(/```/g, "")
    .trim();
}

// Try to extract a JSON object from AI output. Returns null on failure.

functions._tasExtractJson:
function _tasExtractJson(s) {
  if (!s) return null;
  var t = _tasCleanCode(s);
  // Find first { and last } to handle prose around JSON.
  var first = t.indexOf("{"), last = t.lastIndexOf("}");
  if (first === -1 || last === -1 || last <= first) return null;
  try { return JSON.parse(t.substring(first, last + 1)); }
  catch (_) { return null; }
}

// Snapshot a tool to localStorage history (max 10 entries per tool).

functions._tasSnapshotTool:
function _tasSnapshotTool(tool) {
  if (!tool || !tool.id) return;
  try {
    var key = "_tas_history_" + tool.id;
    var arr = [];
    try { arr = JSON.parse(localStorage.getItem(key) || "[]"); } catch (_) { arr = []; }
    arr.unshift({ at: Date.now(), version: Number(tool.__version) || 0, tool: JSON.parse(JSON.stringify(tool)) });
    if (arr.length > 10) arr = arr.slice(0, 10);
    localStorage.setItem(key, JSON.stringify(arr));
  } catch (e) { console.warn("[TAS] snapshot failed:", e); }
}

functions._tasGetHistory:
function _tasGetHistory(toolId) {
  try { return JSON.parse(localStorage.getItem("_tas_history_" + toolId) || "[]"); }
  catch (_) { return []; }
}

// Lightweight JS beautifier: when AI returns minified single-line code, this
// re-introduces newlines and 2-space indentation. Not a full pretty-printer —
// good enough to make the source readable in the textarea.

functions._tasBeautifyJs:
function _tasBeautifyJs(src) {
  if (!src || typeof src !== "string") return src;
  // If the source already has multiple lines, leave it alone.
  var nlCount = (src.match(/\n/g) || []).length;
  var totalLen = src.length;
  if (nlCount > 0 && nlCount > totalLen / 200) return src; // already reasonably formatted
  // Strip carriage returns, normalize whitespace inside lines.
  var s = src.replace(/\r/g, "");
  // Insert newlines after structural punctuation that's NOT inside a string or comment.
  // Walk char by char tracking string/comment state.
  var out = "";
  var i = 0, n = s.length;
  var inSL = false, inML = false, inStr = false, strCh = "";
  while (i < n) {
    var ch = s[i], next = s[i + 1];
    if (inSL) { out += ch; if (ch === "\n") inSL = false; i++; continue; }
    if (inML) { out += ch; if (ch === "*" && next === "/") { out += next; i += 2; inML = false; continue; } i++; continue; }
    if (inStr) {
      out += ch;
      if (ch === "\\" && i + 1 < n) { out += s[i + 1]; i += 2; continue; }
      if (ch === strCh) inStr = false;
      i++; continue;
    }
    if (ch === "/" && next === "/") { inSL = true; out += ch; i++; continue; }
    if (ch === "/" && next === "*") { inML = true; out += ch; i++; continue; }
    if (ch === '"' || ch === "'" || ch === "`") { inStr = true; strCh = ch; out += ch; i++; continue; }
    if (ch === "{") { out += "{\n"; i++; continue; }
    if (ch === "}") { out += "\n}"; i++; if (s[i] && s[i] !== "\n" && s[i] !== ";" && s[i] !== "," && s[i] !== ")") out += "\n"; continue; }
    if (ch === ";") { out += ";\n"; i++; continue; }
    out += ch; i++;
  }
  // Collapse runs of blank lines.
  out = out.replace(/\n{3,}/g, "\n\n");
  // Re-indent based on brace depth.
  var lines = out.split("\n");
  var depth = 0;
  var indented = lines.map(function (ln) {
    var trimmed = ln.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "}") depth = Math.max(0, depth - 1);
    var pad = "";
    for (var k = 0; k < depth; k++) pad += "  ";
    var result = pad + trimmed;
    var opens = (trimmed.match(/{/g) || []).length;
    var closes = (trimmed.match(/}/g) || []).length;
    depth += opens - closes;
    if (depth < 0) depth = 0;
    return result;
  });
  return indented.join("\n").replace(/\s+$/g, "") + "\n";
}

functions._tasAiCreateTab:
function _tasAiCreateTab(content) {
  // Per-mount state.
